// utm-tracking.js - Pass UTM parameters to Gumroad checkout links

(function() {
    'use strict';

    // UTM parameters to track
    const UTM_PARAMS = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content'];

    /**
     * Get UTM parameters from current URL
     * Also adds language info if not present in utm_content
     * @returns {Object} Object with UTM parameters
     */
    function getUTMParams() {
        const urlParams = new URLSearchParams(window.location.search);
        const utmParams = {};
        
        UTM_PARAMS.forEach(param => {
            const value = urlParams.get(param);
            if (value) {
                utmParams[param] = value;
            }
        });
        
        // Get current language from the page or localStorage
        const currentLang = window.currentLanguage || 
                           localStorage.getItem('userLanguage') || 
                           document.documentElement.lang || 
                           'en';
        
        // Add language to tracking - append to utm_content or create new
        if (utmParams.utm_content) {
            // Append language if not already present
            if (!utmParams.utm_content.includes('_lang-')) {
                utmParams.utm_content = utmParams.utm_content + '_lang-' + currentLang;
            }
        } else if (Object.keys(utmParams).length > 0) {
            // Only add lang if there are other UTM params
            utmParams.utm_content = 'lang-' + currentLang;
        }
        
        return utmParams;
    }

    /**
     * Append UTM parameters to a URL
     * @param {string} url - Original URL
     * @param {Object} utmParams - UTM parameters to append
     * @returns {string} URL with UTM parameters
     */
    function appendUTMToUrl(url, utmParams) {
        if (Object.keys(utmParams).length === 0) {
            return url;
        }

        try {
            const urlObj = new URL(url);
            
            // Append each UTM parameter
            Object.entries(utmParams).forEach(([key, value]) => {
                urlObj.searchParams.set(key, value);
            });
            
            return urlObj.toString();
        } catch (e) {
            // If URL parsing fails, return original
            console.warn('UTM Tracking: Could not parse URL', url);
            return url;
        }
    }

    /**
     * Update all Gumroad links with UTM parameters
     */
    function updateGumroadLinks() {
        const utmParams = getUTMParams();
        
        // Skip if no UTM params present
        if (Object.keys(utmParams).length === 0) {
            return;
        }

        // Find all links to Gumroad
        const gumroadLinks = document.querySelectorAll('a[href*="gumroad.com"]');
        
        gumroadLinks.forEach(link => {
            const originalHref = link.getAttribute('href');
            const newHref = appendUTMToUrl(originalHref, utmParams);
            link.setAttribute('href', newHref);
        });

        console.log('UTM Tracking: Updated', gumroadLinks.length, 'Gumroad links with UTM params:', utmParams);
    }

    /**
     * Handle dynamically created links or button clicks
     * Intercept clicks on CTA buttons and add UTM to their actions
     */
    function setupClickTracking() {
        const utmParams = getUTMParams();
        
        if (Object.keys(utmParams).length === 0) {
            return;
        }

        // Store UTM params in sessionStorage for dynamic links
        sessionStorage.setItem('utm_params', JSON.stringify(utmParams));

        // Handle tier CTA buttons that might redirect via JavaScript
        document.addEventListener('click', function(e) {
            const target = e.target.closest('.tier-cta');
            if (!target) return;

            // Check if this button has a data attribute for Gumroad URL
            const gumroadUrl = target.dataset.gumroadUrl;
            if (gumroadUrl) {
                e.preventDefault();
                const finalUrl = appendUTMToUrl(gumroadUrl, utmParams);
                window.open(finalUrl, '_blank');
            }
        });
    }

    /**
     * Get stored UTM params (for dynamic link generation)
     * @returns {Object} Stored UTM parameters
     */
    window.getStoredUTMParams = function() {
        try {
            return JSON.parse(sessionStorage.getItem('utm_params')) || {};
        } catch (e) {
            return {};
        }
    };

    /**
     * Build a Gumroad URL with UTM tracking
     * @param {string} baseUrl - Base Gumroad URL
     * @returns {string} URL with UTM parameters
     */
    window.buildGumroadUrl = function(baseUrl) {
        const utmParams = window.getStoredUTMParams();
        return appendUTMToUrl(baseUrl, utmParams);
    };

    // Initialize when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            updateGumroadLinks();
            setupClickTracking();
        });
    } else {
        updateGumroadLinks();
        setupClickTracking();
    }

    // Also update links after any dynamic content changes
    // Watch for translations loading which might affect links
    document.addEventListener('translationsLoaded', updateGumroadLinks);

    /**
     * Highlight story card based on URL parameter
     * Example: ?historia=paris will highlight the Paris story card
     */
    function highlightStoryFromURL() {
        const urlParams = new URLSearchParams(window.location.search);
        const historiaParam = urlParams.get('historia');
        
        if (!historiaParam) return;

        // Find the story card with matching data-story attribute
        const storyCard = document.querySelector(`.story-card[data-story="${historiaParam.toLowerCase()}"]`);
        
        if (storyCard) {
            // Add highlighted class
            storyCard.classList.add('highlighted');
            
            // Scroll to the archive section smoothly after a short delay
            setTimeout(() => {
                const archiveSection = document.getElementById('archivo');
                if (archiveSection) {
                    archiveSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            }, 500);
            
            console.log('Story Highlight: Highlighted story card for:', historiaParam);
        } else {
            console.log('Story Highlight: No matching story card found for:', historiaParam);
        }
    }

    // Initialize story highlighting when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', highlightStoryFromURL);
    } else {
        highlightStoryFromURL();
    }

})();


/**
 * Waitlist Form Handler
 * Simple email capture for the upcoming book release
 */

// Gumroad checkout URL base
const GUMROAD_CHECKOUT_URL = 'https://gumroad.com/checkout?product=fywme&option=ArbuNBmxLE4TtR90oTUedg%3D%3D&quantity=1';

function submitWaitlist(e) {
    // Prevent default form submission
    if (e) e.preventDefault();
    
    const emailInput = document.getElementById('waitlistEmail');
    const form = document.querySelector('.waitlist-form');
    const btn = document.getElementById('waitlistBtn');
    
    if (!emailInput || !form) return;
    
    const email = emailInput.value.trim();
    
    // Basic email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
        emailInput.style.borderColor = '#ef4444';
        emailInput.placeholder = 'Por favor, introduce un email válido';
        emailInput.value = '';
        setTimeout(() => {
            emailInput.style.borderColor = 'rgba(212, 175, 55, 0.3)';
            emailInput.placeholder = 'tu@email.com';
        }, 2000);
        return;
    }
    
    // Show loading state
    const originalText = btn.textContent;
    btn.textContent = 'Redirigiendo...';
    btn.disabled = true;
    
    // Log for analytics (if available)
    if (typeof gtag !== 'undefined') {
        gtag('event', 'checkout_redirect', {
            'event_category': 'conversion',
            'event_label': 'DON Gumroad Checkout'
        });
    }
    
    // Redirect to Gumroad checkout with email pre-filled
    const encodedEmail = encodeURIComponent(email);
    
    // Add UTM params if available (using utm-tracking.js helper)
    let checkoutUrl = GUMROAD_CHECKOUT_URL;
    if (window.buildGumroadUrl) {
        checkoutUrl = window.buildGumroadUrl(GUMROAD_CHECKOUT_URL);
    }
    
    // Append email
    // Check if url already has params (it usually does for Gumroad)
    const separator = checkoutUrl.includes('?') ? '&' : '?';
    checkoutUrl = `${checkoutUrl}${separator}email=${encodedEmail}`;
    
    // Small delay for visual feedback, then redirect
    setTimeout(() => {
        window.location.href = checkoutUrl;
    }, 300);
}

// Allow form submission with Enter key
document.addEventListener('DOMContentLoaded', function() {
    const emailInput = document.getElementById('waitlistEmail');
    if (emailInput) {
        emailInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                e.preventDefault();
                submitWaitlist();
            }
        });
    }
});

// Floating preorder button visibility and language toggle

document.addEventListener('DOMContentLoaded', () => {
  const floatingBtn = document.getElementById('preorderBtn');
  const heroSection = document.querySelector('.hero');
  const preorderSection = document.getElementById('preorder');
  const langToggleBtn = document.getElementById('langToggleBtn');

  let isPastHero = false;

  // --- Hero Observer for language toggle visibility ---
  const heroObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      const pastAndBelow = !entry.isIntersecting && entry.boundingClientRect.bottom < 0;
      isPastHero = pastAndBelow;

      // Language toggle visibility
      if (langToggleBtn) {
        if (isPastHero) {
          langToggleBtn.classList.add('hidden');
        } else {
          langToggleBtn.classList.remove('hidden');
        }
      }
    });
  }, { threshold: 0 });

  if (heroSection) heroObserver.observe(heroSection);

  // --- Scroll listener for floating button (show at 50% of page) ---
  function updateFloatingButtonVisibility() {
    const scrollPosition = window.scrollY;
    const documentHeight = document.documentElement.scrollHeight - window.innerHeight;
    const scrollPercentage = scrollPosition / documentHeight;

    // Show button when scrolled past 50% of the page
    if (scrollPercentage > 0.5) {
      floatingBtn.classList.add('visible');
    } else {
      floatingBtn.classList.remove('visible');
    }
  }

  window.addEventListener('scroll', updateFloatingButtonVisibility);
  updateFloatingButtonVisibility(); // Initial check

  // --- Click handler for floating button - always scroll to preorder ---
  floatingBtn.addEventListener('click', function () {
    preorderSection.scrollIntoView({
      behavior: 'smooth'
    });
  });

  // Scroll suave al hacer clic en la flecha del hero
  document.querySelector('.scroll-indicator').addEventListener('click', function () {
    window.scrollBy({
      top: window.innerHeight,
      behavior: 'smooth'
    });
  });

  // Hero CTA button - scroll to preorder
  const heroCta = document.querySelector('.hero .cta-button');
  if (heroCta) {
    heroCta.addEventListener('click', function (e) {
      e.preventDefault();
      preorderSection.scrollIntoView({
        behavior: 'smooth'
      });
    });
  }
});

